// The reason for removing the Item
//
// `FRAUD_FIRST_PARTY`: The end user who owns the connected bank account committed fraud
//
// `FRAUD_FALSE_IDENTITY`: The end user created the connection using false identity information or stolen credentials
//
// `FRAUD_ABUSE`: The end user is abusing the client's service or platform through their connected account
//
// `FRAUD_OTHER`: Other fraud-related reasons involving the end user not covered by the specific fraud categories
//
// `CONNECTION_IS_NON_FUNCTIONAL`: The connection to the end user's financial institution is broken and cannot be restored
//
// `OTHER`: Any other reason for removing the connection not covered by the above categories
type ItemRemoveReasonCode string

const (
	ItemRemoveReasonCodeFraudFirstParty           ItemRemoveReasonCode = "FRAUD_FIRST_PARTY"
	ItemRemoveReasonCodeFraudFalseIdentity        ItemRemoveReasonCode = "FRAUD_FALSE_IDENTITY"
	ItemRemoveReasonCodeFraudAbuse                ItemRemoveReasonCode = "FRAUD_ABUSE"
	ItemRemoveReasonCodeFraudOther                ItemRemoveReasonCode = "FRAUD_OTHER"
	ItemRemoveReasonCodeConnectionIsNonFunctional ItemRemoveReasonCode = "CONNECTION_IS_NON_FUNCTIONAL"
	ItemRemoveReasonCodeOther                     ItemRemoveReasonCode = "OTHER"
)

func NewItemRemoveReasonCodeFromString(s string) (ItemRemoveReasonCode, error) {
	switch s {
	case "FRAUD_FIRST_PARTY":
		return ItemRemoveReasonCodeFraudFirstParty, nil
	case "FRAUD_FALSE_IDENTITY":
		return ItemRemoveReasonCodeFraudFalseIdentity, nil
	case "FRAUD_ABUSE":
		return ItemRemoveReasonCodeFraudAbuse, nil
	case "FRAUD_OTHER":
		return ItemRemoveReasonCodeFraudOther, nil
	case "CONNECTION_IS_NON_FUNCTIONAL":
		return ItemRemoveReasonCodeConnectionIsNonFunctional, nil
	case "OTHER":
		return ItemRemoveReasonCodeOther, nil
	}
	var t ItemRemoveReasonCode
	return "", fmt.Errorf("%s is not a valid %T", s, t)
}

